# Variant: Reputation-sensitive Defector
# Evaluate updates reputation based on observed cooperation/defection
# Decide cooperates only if recipient reputation is high, else defects.

THRESHOLD = 0.5   # cooperation threshold
ALPHA = 0.2        # learning rate for reputation update

def evaluate(current_reputation, observation, my_history, round_num):
    if observation['action'] == 'cooperate':
        delta = 1.0
    else:
        delta = -1.0
    new_reputation = current_reputation + ALPHA * (delta - current_reputation)
    return max(-1.0, min(1.0, new_reputation))

def decide(recipient_reputation, round_num, my_history):
    return recipient_reputation > THRESHOLD
